PY_MINI = [
MINI(1, 'API catatan pribadi dengan tag',
  'Aplikasi catatan butuh API di mana setiap pengguna hanya bisa melihat dan mengubah catatannya sendiri, dan bisa memfilter berdasarkan tag.',
  ['CRUD catatan lewat REST API', 'Catatan hanya terlihat oleh pemiliknya (pengguna lain mendapat 404)', 'Tag banyak-ke-banyak dan filter <code>?tag=kuliah</code>', 'Test untuk aturan kepemilikan'],
  ['Model <code>Catatan</code> dengan <code>pemilik</code> (FK ke User) dan <code>tags</code> (ManyToMany ke Tag).', 'Batasi queryset di <code>get_queryset()</code> ke <code>pemilik=request.user</code>; data orang lain otomatis 404, bukan 403, sehingga keberadaannya tidak bocor.', 'Serializer menerima daftar nama tag lalu <code>get_or_create</code> setiap tag.', 'Test dengan dua pengguna: A tidak bisa membaca catatan B.'],
  "# catatan/models.py\nfrom django.conf import settings\nfrom django.db import models\n\nclass Tag(models.Model):\n    nama = models.SlugField(max_length=30, unique=True)\n\nclass Catatan(models.Model):\n    pemilik = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name='catatan')\n    judul = models.CharField(max_length=120)\n    isi = models.TextField(blank=True)\n    tags = models.ManyToManyField(Tag, blank=True)\n    diubah = models.DateTimeField(auto_now=True)\n\n# catatan/serializers.py\nfrom rest_framework import serializers\n\nclass CatatanSerializer(serializers.ModelSerializer):\n    tags = serializers.ListField(child=serializers.SlugField(), required=False)\n\n    class Meta:\n        model = Catatan\n        fields = ['id', 'judul', 'isi', 'tags', 'diubah']\n\n    def to_representation(self, obj):\n        d = super().to_representation(obj)\n        d['tags'] = [t.nama for t in obj.tags.all()]\n        return d\n\n    def _set_tags(self, obj, nama):\n        obj.tags.set([Tag.objects.get_or_create(nama=n.lower())[0] for n in nama])\n\n    def create(self, data):\n        nama = data.pop('tags', [])\n        obj = Catatan.objects.create(**data)\n        self._set_tags(obj, nama)\n        return obj\n\n    def update(self, obj, data):\n        nama = data.pop('tags', None)\n        obj = super().update(obj, data)\n        if nama is not None:\n            self._set_tags(obj, nama)\n        return obj\n\n# catatan/views.py\nfrom rest_framework import viewsets\n\nclass CatatanViewSet(viewsets.ModelViewSet):\n    serializer_class = CatatanSerializer\n\n    def get_queryset(self):\n        qs = Catatan.objects.filter(pemilik=self.request.user).prefetch_related('tags').order_by('-diubah')\n        tag = self.request.query_params.get('tag')\n        return qs.filter(tags__nama=tag) if tag else qs\n\n    def perform_create(self, serializer):\n        serializer.save(pemilik=self.request.user)\n\n# catatan/tests.py\nimport pytest\nfrom django.contrib.auth.models import User\nfrom rest_framework.test import APIClient\n\n@pytest.mark.django_db\ndef test_tidak_bisa_baca_catatan_orang_lain():\n    a, b = User.objects.create_user('a'), User.objects.create_user('b')\n    c = Catatan.objects.create(pemilik=b, judul='Rahasia B')\n    api = APIClient(); api.force_authenticate(a)\n    assert api.get(f'/api/catatan/{c.id}/').status_code == 404",
  'python', kunci='pencarian full-text dan berbagi catatan ke pengguna lain dengan izin baca saja.',
  cek=q('Kenapa catatan milik orang lain mengembalikan 404, bukan 403?', ['Agar keberadaan data orang lain tidak bocor', 'Karena 403 tidak ada di DRF', 'Agar lebih cepat'], 0, 'Queryset sudah dibatasi ke pemilik.')),

MINI(2, 'Penerima webhook pembayaran yang aman dan idempoten',
  'Payment gateway mengirim notifikasi "pembayaran berhasil" ke server. Penyerang bisa memalsukannya, dan gateway bisa mengirim notifikasi yang sama berkali-kali.',
  ['Tolak webhook yang tanda tangannya salah', 'Notifikasi yang sama hanya diproses sekali', 'Status hanya boleh maju (MENUNGGU → DIBAYAR), tidak mundur', 'Selalu balas cepat 200 agar gateway tidak mengulang terus'],
  ['Hitung HMAC-SHA256 dari body mentah dengan kunci rahasia, bandingkan dengan <code>hmac.compare_digest</code> (aman dari timing attack).', 'Simpan id event yang sudah diproses; jika sudah ada, langsung balas "duplikat".', 'Gunakan tabel transisi status yang diizinkan.', 'Pisahkan logika ke fungsi murni agar mudah diuji (kode di bawah bisa dijalankan).'],
  "import hashlib, hmac, json\n\nRAHASIA = b'kunci-rahasia-dari-dashboard'\nBOLEH = {('MENUNGGU', 'DIBAYAR'), ('MENUNGGU', 'KEDALUWARSA'), ('DIBAYAR', 'DIKEMBALIKAN')}\npesanan = {'PSN-41': 'MENUNGGU'}\nsudah_diproses = set()            # di produksi: tabel dengan UNIQUE(event_id)\n\ndef tanda_tangan(body: bytes) -> str:\n    return hmac.new(RAHASIA, body, hashlib.sha256).hexdigest()\n\ndef terima_webhook(body: bytes, sig: str):\n    if not hmac.compare_digest(tanda_tangan(body), sig):\n        return 401, 'tanda tangan salah'\n    e = json.loads(body)\n    if e['event_id'] in sudah_diproses:\n        return 200, 'duplikat, diabaikan'\n    lama, baru = pesanan.get(e['order_id']), e['status']\n    if (lama, baru) not in BOLEH:\n        sudah_diproses.add(e['event_id'])\n        return 200, f'transisi {lama} -> {baru} ditolak'\n    pesanan[e['order_id']] = baru\n    sudah_diproses.add(e['event_id'])\n    return 200, f'{e[\"order_id\"]}: {lama} -> {baru}'\n\nbody = json.dumps({'event_id': 'ev-1', 'order_id': 'PSN-41', 'status': 'DIBAYAR'}).encode()\nprint(terima_webhook(body, tanda_tangan(body)))\nprint(terima_webhook(body, tanda_tangan(body)))           # dikirim ulang oleh gateway\nprint(terima_webhook(body, 'palsu123'))                   # dipalsukan\nmundur = json.dumps({'event_id': 'ev-2', 'order_id': 'PSN-41', 'status': 'MENUNGGU'}).encode()\nprint(terima_webhook(mundur, tanda_tangan(mundur)))\nprint('status akhir:', pesanan)",
  'python', run=True, kunci='pasang di view Django (<code>request.body</code> mentah, <code>csrf_exempt</code>) dan proses berat di Celery agar balasan tetap cepat.',
  cek=q('Kenapa memakai hmac.compare_digest, bukan ==?', ['Waktu perbandingannya konstan sehingga aman dari timing attack', 'Lebih pendek ditulis', 'Karena == tidak bisa membandingkan string'], 0, '== berhenti di karakter pertama yang beda.')),

MINI(3, 'Pembatas request (rate limiter) token bucket',
  'API login dan API AI mahal sering disalahgunakan bot. Setiap pengguna perlu dibatasi, misalnya 5 request per 10 detik dengan sedikit kelonggaran.',
  ['Batas per pengguna/IP, tidak memengaruhi pengguna lain', 'Mengizinkan ledakan kecil (burst) lalu mengisi ulang perlahan', 'Mengembalikan 429 dan header <code>Retry-After</code>', 'Bisa diuji tanpa menunggu waktu sungguhan'],
  ['Token bucket: setiap pengguna punya ember berkapasitas N token; setiap request mengambil 1 token; token terisi ulang r per detik.', 'Hitung isi ulang secara malas saat request datang: <code>token += (sekarang - terakhir) × r</code>, dibatasi kapasitas.', 'Jika token &lt; 1, tolak dan hitung berapa detik sampai token berikutnya tersedia.', 'Suntikkan fungsi waktu (<code>jam</code>) agar test bisa memajukan waktu sesuka hati. Di produksi simpan state di Redis.'],
  "import math\n\nclass TokenBucket:\n    def __init__(self, kapasitas, isi_per_detik, jam):\n        self.k, self.r, self.jam = kapasitas, isi_per_detik, jam\n        self.ember = {}                       # kunci -> (token, waktu_terakhir)\n\n    def izinkan(self, kunci):\n        now = self.jam()\n        token, t = self.ember.get(kunci, (self.k, now))\n        token = min(self.k, token + (now - t) * self.r)\n        if token >= 1:\n            self.ember[kunci] = (token - 1, now)\n            return True, 0\n        self.ember[kunci] = (token, now)\n        return False, math.ceil((1 - token) / self.r)   # detik untuk Retry-After\n\nwaktu = [0.0]\nrl = TokenBucket(kapasitas=5, isi_per_detik=0.5, jam=lambda: waktu[0])\n\nhasil = [rl.izinkan('ip-1')[0] for _ in range(7)]\nprint('7 request beruntun dari ip-1:', hasil)\nprint('ip-2 tidak terpengaruh      :', rl.izinkan('ip-2'))\nprint('ip-1 ditolak, Retry-After   :', rl.izinkan('ip-1')[1], 'detik')\nwaktu[0] += 4\nprint('4 detik kemudian            :', [rl.izinkan('ip-1')[0] for _ in range(3)])",
  'python', run=True, kunci='pasang sebagai middleware Django yang memakai Redis (<code>INCR</code> + <code>EXPIRE</code> atau skrip Lua) agar berlaku di beberapa server.',
  cek=q('Status HTTP yang tepat saat batas terlampaui?', ['429 Too Many Requests', '403 Forbidden', '500'], 0, 'Sertakan header Retry-After.')),

MINI(4, 'Unggah foto produk dengan validasi dan thumbnail',
  'Penjual mengunggah foto dari HP berukuran 5–10 MB. Server harus menolak berkas berbahaya dan membuat versi kecil agar katalog cepat dimuat.',
  ['Hanya JPEG/PNG/WebP, maksimal 5 MB, diperiksa dari isi berkas (bukan nama)', 'Simpan versi asli dan thumbnail 400 px dalam WebP', 'Nama berkas acak agar tidak menimpa dan tidak bisa ditebak', 'Pembuatan thumbnail di latar belakang agar respons cepat'],
  ['Buka berkas dengan Pillow dan cek <code>img.format</code>; berkas teks yang diganti namanya menjadi .jpg akan gagal dibuka.', 'Koreksi orientasi EXIF dari kamera HP dengan <code>ImageOps.exif_transpose</code>, lalu hapus metadata lokasi.', 'Simpan ke <code>uuid4().hex</code> + ekstensi; di produksi gunakan storage S3-compatible (django-storages).', 'Kirim tugas Celery <code>buat_thumbnail.delay(id)</code> setelah transaksi commit.'],
  "# produk/validators.py\nfrom PIL import Image, ImageOps, UnidentifiedImageError\nfrom django.core.exceptions import ValidationError\n\nMAKS = 5 * 1024 * 1024\nFORMAT = {'JPEG', 'PNG', 'WEBP'}\n\ndef validasi_foto(berkas):\n    if berkas.size > MAKS:\n        raise ValidationError('Ukuran foto maksimal 5 MB.')\n    try:\n        with Image.open(berkas) as img:\n            img.verify()                       # cek isi berkas benar-benar gambar\n            if img.format not in FORMAT:\n                raise ValidationError('Format harus JPEG, PNG, atau WebP.')\n    except UnidentifiedImageError:\n        raise ValidationError('Berkas bukan gambar yang valid.')\n    berkas.seek(0)\n\n# produk/models.py\nimport uuid\nfrom django.db import models, transaction\n\ndef jalur_foto(obj, nama):\n    return f'produk/{uuid.uuid4().hex}.{nama.rsplit(\".\", 1)[-1].lower()}'\n\nclass FotoProduk(models.Model):\n    produk = models.ForeignKey('Produk', on_delete=models.CASCADE, related_name='foto')\n    asli = models.ImageField(upload_to=jalur_foto, validators=[validasi_foto])\n    thumb = models.ImageField(upload_to='produk/thumb/', blank=True)\n\n    def save(self, *a, **kw):\n        baru = self.pk is None\n        super().save(*a, **kw)\n        if baru:\n            transaction.on_commit(lambda: buat_thumbnail.delay(self.pk))\n\n# produk/tasks.py\nfrom io import BytesIO\nfrom celery import shared_task\nfrom django.core.files.base import ContentFile\n\n@shared_task(autoretry_for=(OSError,), retry_backoff=True, max_retries=3)\ndef buat_thumbnail(pk):\n    f = FotoProduk.objects.get(pk=pk)\n    with Image.open(f.asli) as img:\n        img = ImageOps.exif_transpose(img).convert('RGB')     # putar sesuai kamera, buang EXIF\n        img.thumbnail((400, 400))\n        buf = BytesIO()\n        img.save(buf, 'WEBP', quality=80)\n    f.thumb.save(f'{uuid.uuid4().hex}.webp', ContentFile(buf.getvalue()), save=True)",
  'python', kunci='URL bertanda tangan (presigned) agar HP mengunggah langsung ke storage tanpa melewati server.',
  cek=q('Kenapa tipe berkas dicek dengan membuka isinya, bukan dari ekstensi?', ['Ekstensi bisa diganti sembarangan oleh penyerang', 'Agar lebih cepat', 'Karena Django tidak tahu ekstensi'], 0, 'Selalu periksa isi.')),

MINI(5, 'Pencarian full-text bahasa Indonesia di PostgreSQL',
  'Pencarian <code>icontains</code> lambat dan tidak menemukan "kopi susu" saat pengguna mengetik "susu kopi". Toko butuh pencarian yang memberi peringkat relevansi.',
  ['Cari di nama (bobot tinggi) dan deskripsi (bobot rendah)', 'Urutkan berdasarkan relevansi', 'Toleran salah ketik ringan dengan trigram', 'Tetap cepat untuk 100 ribu produk (index GIN)'],
  ['Tambah kolom <code>SearchVectorField</code> yang diisi trigger/<code>GeneratedField</code>, dengan bobot A untuk nama dan B untuk deskripsi.', 'Cari dengan <code>SearchQuery(..., search_type="websearch")</code> agar pengguna bisa memakai tanda kutip dan minus.', 'Jika hasil kosong, jatuh ke <code>TrigramSimilarity</code> untuk salah ketik.', 'Buat index GIN untuk vektor dan untuk trigram.'],
  "# produk/models.py\nfrom django.contrib.postgres.indexes import GinIndex\nfrom django.contrib.postgres.search import SearchVector, SearchVectorField\nfrom django.db import models\n\nclass Produk(models.Model):\n    nama = models.CharField(max_length=120)\n    deskripsi = models.TextField(blank=True)\n    cari = models.GeneratedField(\n        expression=SearchVector('nama', weight='A', config='simple') + SearchVector('deskripsi', weight='B', config='simple'),\n        output_field=SearchVectorField(), db_persist=True)\n\n    class Meta:\n        indexes = [GinIndex(fields=['cari']), GinIndex(name='produk_nama_trgm', fields=['nama'], opclasses=['gin_trgm_ops'])]\n\n# produk/search.py\nfrom django.contrib.postgres.search import SearchQuery, SearchRank, TrigramSimilarity\nfrom django.db.models import F\n\ndef cari_produk(teks: str, batas=20):\n    q = SearchQuery(teks, config='simple', search_type='websearch')\n    hasil = (Produk.objects.filter(cari=q)\n             .annotate(skor=SearchRank(F('cari'), q)).order_by('-skor')[:batas])\n    if hasil:\n        return list(hasil)\n    # cadangan untuk salah ketik: \"kopi gyo\" -> \"Kopi Gayo\"\n    return list(Produk.objects.annotate(skor=TrigramSimilarity('nama', teks))\n                .filter(skor__gt=0.25).order_by('-skor')[:batas])\n\n# migrasi: aktifkan ekstensi trigram\n# from django.contrib.postgres.operations import TrigramExtension\n# operations = [TrigramExtension(), ...]",
  'python', out="cari_produk('susu kopi')   -> Kopi Susu Aren (0.61), Es Kopi Susu (0.45)\ncari_produk('kopi -susu')  -> Kopi Gayo 200g (0.30), Kopi Toraja (0.30)\ncari_produk('kopi gyo')    -> Kopi Gayo 200g (trigram 0.53)",
  kunci='kamus sinonim (es = ice, susu = milk) dan analitik kata kunci yang tidak menemukan hasil.',
  cek=q('Index yang tepat untuk kolom tsvector?', ['GIN', 'B-tree', 'Hash'], 0, 'GIN untuk pencarian full-text dan trigram.')),

MINI(6, 'Notifikasi email terjadwal dengan Celery dan retry',
  'Murid lupa tenggat tugas. Sistem perlu mengirim pengingat H-1 setiap pagi tanpa memperlambat request, dan tetap terkirim walau server email sedang gangguan.',
  ['Tugas terjadwal setiap 07.00 WIB mencari tenggat besok', 'Kirim email per murid di latar belakang', 'Ulangi otomatis dengan jeda bertambah jika server email gagal', 'Tidak mengirim pengingat ganda'],
  ['Pasang Celery dengan broker Redis dan Celery Beat untuk jadwal (<code>crontab(hour=7)</code>, zona waktu Asia/Jakarta).', 'Tugas penjadwal hanya mencari data lalu memecahnya menjadi tugas kecil per murid.', 'Tugas kirim memakai <code>autoretry_for</code>, <code>retry_backoff</code>, dan <code>max_retries</code>.', 'Catat pengingat terkirim di tabel dengan <code>UniqueConstraint(tugas, murid)</code> agar idempoten.'],
  "# config/celery.py\nfrom celery import Celery\nfrom celery.schedules import crontab\n\napp = Celery('kelas')\napp.config_from_object('django.conf:settings', namespace='CELERY')\napp.conf.timezone = 'Asia/Jakarta'\napp.conf.beat_schedule = {'pengingat-tenggat': {'task': 'kelas.tasks.jadwalkan_pengingat', 'schedule': crontab(hour=7, minute=0)}}\napp.autodiscover_tasks()\n\n# kelas/models.py (potongan)\nclass PengingatTerkirim(models.Model):\n    tugas = models.ForeignKey('Tugas', on_delete=models.CASCADE)\n    murid = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE)\n    waktu = models.DateTimeField(auto_now_add=True)\n    class Meta:\n        constraints = [models.UniqueConstraint(fields=['tugas', 'murid'], name='satu_pengingat')]\n\n# kelas/tasks.py\nfrom datetime import timedelta\nfrom smtplib import SMTPException\nfrom celery import shared_task\nfrom django.core.mail import send_mail\nfrom django.db import IntegrityError\nfrom django.utils import timezone\n\n@shared_task\ndef jadwalkan_pengingat():\n    besok = timezone.localdate() + timedelta(days=1)\n    for tugas in Tugas.objects.filter(tenggat__date=besok).prefetch_related('kelas__murid'):\n        for murid in tugas.kelas.murid.exclude(pengumpulan__tugas=tugas):\n            kirim_pengingat.delay(tugas.id, murid.id)\n\n@shared_task(autoretry_for=(SMTPException, ConnectionError), retry_backoff=30, retry_jitter=True, max_retries=5)\ndef kirim_pengingat(tugas_id, murid_id):\n    try:\n        catat = PengingatTerkirim.objects.create(tugas_id=tugas_id, murid_id=murid_id)\n    except IntegrityError:\n        return 'sudah pernah dikirim'\n    t, m = catat.tugas, catat.murid\n    try:\n        send_mail(f'Pengingat: {t.judul} besok', f'Halo {m.first_name}, tugas \"{t.judul}\" ditutup {t.tenggat:%d/%m %H.%M}.',\n                  None, [m.email])\n    except Exception:\n        catat.delete()          # biarkan retry mencoba lagi\n        raise\n    return 'terkirim'\n\n# terminal\n# celery -A config worker -l info\n# celery -A config beat -l info",
  'python', kunci='kanal WhatsApp (Business API) sebagai pilihan, dan halaman preferensi notifikasi murid.',
  cek=q('Kenapa pengiriman dipecah menjadi satu tugas per murid?', ['Agar kegagalan satu email tidak menggagalkan semua, dan bisa di-retry sendiri', 'Agar kode lebih panjang', 'Karena Celery membatasi satu email per server'], 0, 'Tugas kecil, independen, idempoten.')),
]

PY_BESAR = [
BESAR(1, 'Platform kelas online (LMS) dengan pembayaran',
  'Guru les dan kursus kecil ingin menjual kelas video, memberi kuis, dan memantau progres murid tanpa membayar platform mahal.',
  ['Peran guru, murid, admin dengan izin berbeda', 'Guru membuat kelas → modul → pelajaran (video/teks) dan kuis', 'Murid membeli kelas (pembayaran sandbox), menonton, mengerjakan kuis, melihat progres', 'Sertifikat PDF otomatis saat progres 100%', 'Dashboard guru: murid aktif, pendapatan, nilai rata-rata kuis'],
  'Django 5, DRF, PostgreSQL, Redis, Celery, Midtrans/Xendit sandbox, WeasyPrint, pytest, Docker Compose, Render',
  [('Model', 'Kelas, Modul, Pelajaran, Pendaftaran(murid, kelas, status), Progres(murid, pelajaran), Kuis, Jawaban'),
   ('Izin', 'IsGuruPemilik untuk mengubah kelas; IsTerdaftar untuk membuka pelajaran berbayar'),
   ('Pembayaran', 'Pendaftaran MENUNGGU → webhook terverifikasi → AKTIF (idempoten)'), ('Latar belakang', 'Celery: sertifikat PDF, email selamat datang, rekap mingguan guru')],
  ['Rancang model dan relasi; pakai <code>order</code> untuk urutan modul dan pelajaran.', 'Buat permission per objek dan test untuk setiap peran (guru lain tidak boleh mengubah kelas).', 'Checkout membuat Pendaftaran MENUNGGU dan transaksi gateway; webhook mengaktifkan pendaftaran.', 'Endpoint progres: tandai pelajaran selesai, hitung persentase dengan agregasi database.', 'Saat 100%, Celery membuat sertifikat PDF dengan WeasyPrint dan mengirim email.', 'Dashboard guru memakai satu query agregasi (annotate) untuk menghindari N+1.'],
  "# kelas/permissions.py\nfrom rest_framework.permissions import BasePermission, SAFE_METHODS\n\nclass IsGuruPemilik(BasePermission):\n    def has_object_permission(self, req, view, kelas):\n        return req.method in SAFE_METHODS or kelas.guru_id == req.user.id\n\nclass IsTerdaftar(BasePermission):\n    message = 'Beli kelas ini untuk membuka pelajaran.'\n    def has_object_permission(self, req, view, pelajaran):\n        k = pelajaran.modul.kelas\n        return pelajaran.gratis or k.guru_id == req.user.id or \\\n            k.pendaftaran.filter(murid=req.user, status='AKTIF').exists()\n\n# kelas/views.py\nfrom django.db.models import Count, Q, Avg\nfrom rest_framework import viewsets, decorators, response\n\nclass PelajaranViewSet(viewsets.ReadOnlyModelViewSet):\n    serializer_class = PelajaranSerializer\n    permission_classes = [IsAuthenticated, IsTerdaftar]\n    queryset = Pelajaran.objects.select_related('modul__kelas')\n\n    @decorators.action(detail=True, methods=['post'])\n    def selesai(self, req, pk=None):\n        p = self.get_object()\n        Progres.objects.get_or_create(murid=req.user, pelajaran=p)\n        kelas = p.modul.kelas\n        total = Pelajaran.objects.filter(modul__kelas=kelas).count()\n        beres = Progres.objects.filter(murid=req.user, pelajaran__modul__kelas=kelas).count()\n        persen = round(100 * beres / total)\n        if persen == 100:\n            buat_sertifikat.delay(req.user.id, kelas.id)\n        return response.Response({'persen': persen})\n\nclass DashboardGuru(viewsets.ViewSet):\n    def list(self, req):\n        data = (Kelas.objects.filter(guru=req.user)\n                .annotate(murid_aktif=Count('pendaftaran', filter=Q(pendaftaran__status='AKTIF')),\n                          nilai_kuis=Avg('modul__kuis__jawaban__nilai'))\n                .values('id', 'judul', 'harga', 'murid_aktif', 'nilai_kuis'))\n        return response.Response([{**d, 'pendapatan': d['harga'] * d['murid_aktif']} for d in data])\n\n# kelas/tasks.py\nfrom weasyprint import HTML\n@shared_task\ndef buat_sertifikat(murid_id, kelas_id):\n    s, dibuat = Sertifikat.objects.get_or_create(murid_id=murid_id, kelas_id=kelas_id)\n    if not dibuat:\n        return\n    html = render_to_string('sertifikat.html', {'s': s})\n    s.pdf.save(f'{s.kode}.pdf', ContentFile(HTML(string=html).write_pdf()))\n\n# tests/test_izin.py\ndef test_murid_belum_bayar_tidak_bisa_buka(api_murid, pelajaran_berbayar):\n    r = api_murid.get(f'/api/pelajaran/{pelajaran_berbayar.id}/')\n    assert r.status_code == 403 and 'Beli kelas' in r.data['detail']",
  'python', standar='izin per objek diuji untuk setiap peran, pembayaran idempoten, tugas berat di Celery, dashboard tanpa N+1 query',
  cek=q('Kenapa sertifikat dibuat di Celery?', ['Membuat PDF lambat; request tetap cepat dan bisa di-retry', 'Agar PDF lebih kecil', 'Karena Django tidak bisa membuat PDF'], 0, 'Pekerjaan berat di latar belakang.')),

BESAR(2, 'Booking layanan tanpa jadwal bentrok (barbershop/klinik)',
  'Barbershop dan klinik kecil sering double booking karena reservasi lewat chat. Pelanggan ingin melihat slot kosong dan memesan sendiri.',
  ['Daftar layanan dengan durasi dan staf yang bisa mengerjakan', 'Slot kosong dihitung dari jam kerja, libur, dan booking yang ada', 'Dua pelanggan tidak mungkin memesan slot staf yang sama (dijamin database)', 'Pengingat WhatsApp/email H-1 dan pembatalan dengan tautan', 'Zona waktu benar (WIB/WITA/WIT)'],
  'Django 5, DRF, PostgreSQL (range type + exclusion constraint), Celery, Redis, pytest, Docker',
  [('Model', 'Staf, Layanan(durasi), JamKerja(staf, hari, mulai, selesai), Booking(staf, waktu tstzrange, status)'),
   ('Anti-bentrok', 'ExclusionConstraint: waktu tidak boleh tumpang tindih (&&) untuk staf yang sama (=) bila status aktif'),
   ('Slot', 'Fungsi murni: jam kerja − booking − jeda, dipecah per durasi layanan'), ('Notifikasi', 'Celery Beat: pengingat H-1, tautan batal bertanda tangan')],
  ['Simpan waktu booking sebagai <code>DateTimeRangeField</code> dalam UTC; tampilkan sesuai zona waktu cabang.', 'Pasang <code>ExclusionConstraint</code> dengan ekstensi <code>btree_gist</code>: inilah penjamin utama tidak ada bentrok, bahkan saat dua request datang bersamaan.', 'Tangkap <code>IntegrityError</code> dan balas 409 "slot baru saja diambil".', 'Fungsi slot kosong ditulis murni dan diuji dengan banyak kasus (istirahat siang, libur, booking di tengah).', 'Tautan batal memakai <code>django.core.signing</code> sehingga tidak perlu login.'],
  "# booking/models.py\nfrom django.contrib.postgres.constraints import ExclusionConstraint\nfrom django.contrib.postgres.fields import DateTimeRangeField, RangeOperators\nfrom django.db import models\n\nclass Booking(models.Model):\n    staf = models.ForeignKey('Staf', on_delete=models.PROTECT)\n    layanan = models.ForeignKey('Layanan', on_delete=models.PROTECT)\n    pelanggan = models.ForeignKey('Pelanggan', on_delete=models.PROTECT)\n    waktu = DateTimeRangeField()\n    status = models.CharField(max_length=10, default='AKTIF')\n\n    class Meta:\n        constraints = [ExclusionConstraint(\n            name='tanpa_bentrok',\n            expressions=[('staf', RangeOperators.EQUAL), ('waktu', RangeOperators.OVERLAPS)],\n            condition=models.Q(status='AKTIF'))]\n\n# booking/slot.py  (fungsi murni, mudah diuji)\nfrom datetime import datetime, timedelta\n\ndef slot_kosong(jam_kerja, terpakai, durasi, langkah=timedelta(minutes=15)):\n    \"\"\"jam_kerja & terpakai: list (mulai, selesai). Kembalikan waktu mulai yang muat.\"\"\"\n    hasil = []\n    for mulai, selesai in jam_kerja:\n        t = mulai\n        while t + durasi <= selesai:\n            if all(t + durasi <= a or t >= b for a, b in terpakai):\n                hasil.append(t)\n            t += langkah\n    return hasil\n\n# booking/views.py\nfrom django.db import IntegrityError, transaction\nfrom psycopg.types.range import Range\n\nclass BookingViewSet(viewsets.ModelViewSet):\n    def create(self, req):\n        s = BookingMasukSerializer(data=req.data); s.is_valid(raise_exception=True)\n        mulai = s.validated_data['mulai']; lay = s.validated_data['layanan']\n        try:\n            with transaction.atomic():\n                b = Booking.objects.create(staf=s.validated_data['staf'], layanan=lay, pelanggan=req.user.pelanggan,\n                                           waktu=Range(mulai, mulai + lay.durasi))\n        except IntegrityError:\n            return Response({'detail': 'Slot ini baru saja diambil. Pilih jam lain.'}, status=409)\n        kirim_konfirmasi.delay(b.id)\n        return Response(BookingSerializer(b).data, status=201)\n\n# tests/test_slot.py\ndef test_slot_menghindari_booking_dan_istirahat():\n    h = lambda j, m=0: datetime(2026, 12, 1, j, m)\n    kerja = [(h(9), h(12)), (h(13), h(17))]                 # istirahat 12-13\n    slot = slot_kosong(kerja, [(h(10), h(11))], timedelta(minutes=45), timedelta(minutes=30))\n    assert h(9) in slot and h(10) not in slot and h(11) in slot and h(12) not in slot",
  'python', standar='bentrok dicegah oleh constraint database (bukan hanya cek di kode), konflik dibalas 409, waktu disimpan UTC, fungsi slot diuji',
  cek=q('Kenapa pengecekan bentrok di kode Python saja tidak cukup?', ['Dua request bersamaan bisa lolos cek yang sama; constraint database menjamin di level data', 'Python terlalu lambat', 'Karena slot tidak bisa dihitung di Python'], 0, 'Race condition.')),

BESAR(3, 'SaaS kasir multi-toko (multi-tenant)',
  'Satu aplikasi kasir dipakai ratusan toko. Data toko A tidak boleh pernah terlihat oleh toko B, dan setiap toko bisa mengundang karyawannya sendiri.',
  ['Pendaftaran toko (tenant) dan undangan karyawan dengan peran pemilik/kasir', 'Semua data (produk, pesanan) otomatis terikat ke tenant', 'Isolasi dijamin dua lapis: aplikasi dan Row-Level Security PostgreSQL', 'Paket langganan dengan batas (misal 2 kasir di paket gratis)', 'Log audit: siapa mengubah apa'],
  'Django 5, DRF, PostgreSQL RLS, SimpleJWT, Stripe/Midtrans subscription sandbox, pytest, Docker',
  [('Tenant', 'Model Toko; Keanggotaan(user, toko, peran); header X-Toko atau subdomain menentukan toko aktif'),
   ('Isolasi app', 'Middleware menyimpan toko aktif; manager TenantQuerySet memfilter otomatis'), ('Isolasi DB', "RLS: USING (toko_id = current_setting('app.toko_id')::int)"),
   ('Audit', 'Sinyal post_save/post_delete menulis ke tabel AuditLog')],
  ['Tambahkan <code>toko_id</code> ke setiap tabel bisnis dan index komposit <code>(toko_id, ...)</code>.', 'Middleware memvalidasi keanggotaan pengguna di toko yang diminta, lalu menjalankan <code>SET LOCAL app.toko_id</code> di awal transaksi.', 'Aktifkan RLS di PostgreSQL sebagai jaring pengaman: query yang lupa filter tetap tidak bisa membaca toko lain.', 'Batas paket diperiksa di service layer (bukan di view) dan diuji.', 'Test isolasi: buat dua toko, pastikan semua endpoint tidak membocorkan data silang.'],
  "# tenant/middleware.py\nfrom django.db import connection\nfrom django.http import JsonResponse\n\nclass TokoAktifMiddleware:\n    def __init__(self, get_response): self.get_response = get_response\n\n    def __call__(self, req):\n        kode = req.headers.get('X-Toko')\n        if kode and req.user.is_authenticated:\n            anggota = Keanggotaan.objects.select_related('toko').filter(user=req.user, toko__kode=kode).first()\n            if not anggota:\n                return JsonResponse({'detail': 'Kamu bukan anggota toko ini.'}, status=403)\n            req.toko, req.peran = anggota.toko, anggota.peran\n            with connection.cursor() as c:\n                c.execute(\"SELECT set_config('app.toko_id', %s, false)\", [str(anggota.toko_id)])\n        return self.get_response(req)\n\n# tenant/models.py\nclass TenantQuerySet(models.QuerySet):\n    def milik(self, toko): return self.filter(toko=toko)\n\nclass TenantModel(models.Model):\n    toko = models.ForeignKey('Toko', on_delete=models.CASCADE, db_index=True)\n    objects = TenantQuerySet.as_manager()\n    class Meta: abstract = True\n\nclass Produk(TenantModel):\n    nama = models.CharField(max_length=120)\n    harga = models.DecimalField(max_digits=12, decimal_places=2)\n\n# migrasi: jaring pengaman Row-Level Security\nRLS = '''\nALTER TABLE toko_produk ENABLE ROW LEVEL SECURITY;\nALTER TABLE toko_produk FORCE ROW LEVEL SECURITY;\nCREATE POLICY isolasi_toko ON toko_produk\n  USING (toko_id = current_setting('app.toko_id', true)::int);\n'''\n# operations = [migrations.RunSQL(RLS)]\n\n# tenant/services.py — aturan paket di satu tempat\ndef undang_kasir(toko, email):\n    if toko.paket == 'GRATIS' and toko.keanggotaan.filter(peran='KASIR').count() >= 2:\n        raise BatasPaket('Paket gratis maksimal 2 kasir. Upgrade untuk menambah.')\n    return Undangan.objects.create(toko=toko, email=email, token=secrets.token_urlsafe(24))\n\n# tests/test_isolasi.py\n@pytest.mark.parametrize('url', ['/api/produk/', '/api/pesanan/', '/api/laporan/harian/'])\ndef test_toko_b_tidak_melihat_data_toko_a(url, api_toko_b, data_toko_a):\n    r = api_toko_b.get(url)\n    assert all(item['toko'] != data_toko_a.id for item in r.data.get('results', []))",
  'python', standar='isolasi tenant dua lapis (aplikasi + RLS) dengan test untuk setiap endpoint, aturan paket di service layer, log audit',
  cek=q('Fungsi Row-Level Security pada proyek ini?', ['Jaring pengaman: query yang lupa filter tetap tidak bisa membaca data toko lain', 'Mempercepat query', 'Mengganti autentikasi'], 0, 'Pertahanan berlapis.')),

BESAR(4, 'Layanan triase tiket customer service dengan AI',
  'Tim CS menerima ratusan pesan per hari. Mereka butuh sistem yang otomatis meringkas, memberi kategori dan prioritas, serta menyarankan balasan, dengan manusia tetap memutuskan.',
  ['Terima tiket dari email/form/WhatsApp ke satu antrean', 'LLM menghasilkan ringkasan, kategori, prioritas, dan draf balasan dalam JSON terstruktur', 'Agen CS menyetujui, mengedit, atau menolak saran (human-in-the-loop)', 'Data pribadi (nomor HP, NIK) disamarkan sebelum dikirim ke model', 'Evaluasi: akurasi kategori dibanding label manusia, biaya per tiket, waktu respons'],
  'Django 5, DRF, Celery, PostgreSQL, Claude API (structured output via tool use), pytest, Langfuse/log sendiri untuk evaluasi',
  [('Alur', 'Tiket masuk → Celery triase → simpan saran → agen meninjau → balasan dikirim'),
   ('Keluaran model', 'Skema tetap {ringkasan, kategori, prioritas, draf_balasan, yakin} divalidasi Pydantic'),
   ('Privasi', 'Regex menyamarkan nomor HP, email, NIK sebelum dikirim; teks asli tetap di database'), ('Evaluasi', 'Set 200 tiket berlabel; laporan akurasi per kategori setiap ganti prompt/model')],
  ['Definisikan kategori yang tetap (Pembayaran, Pengiriman, Akun, Produk, Lainnya) dan aturan prioritas.', 'Saring data pribadi dulu, lalu panggil model dengan instruksi jelas dan skema keluaran; validasi dengan Pydantic, ulangi sekali jika tidak valid.', 'Jalankan di Celery dengan retry dan batas waktu; jika model gagal, tiket tetap masuk antrean tanpa saran.', 'Simpan saran terpisah dari keputusan agen; catat apakah agen menyetujui atau mengedit.', 'Buat perintah <code>manage.py evaluasi_triase</code> untuk menghitung akurasi pada set berlabel.'],
  "# triase/llm.py\nimport json, re\nimport anthropic\nfrom pydantic import BaseModel, Field, ValidationError\nfrom typing import Literal\n\nclass Saran(BaseModel):\n    ringkasan: str = Field(max_length=300)\n    kategori: Literal['Pembayaran', 'Pengiriman', 'Akun', 'Produk', 'Lainnya']\n    prioritas: Literal['tinggi', 'sedang', 'rendah']\n    draf_balasan: str\n    yakin: float = Field(ge=0, le=1)\n\nPOLA = [(re.compile(r'(\\+62|0)8\\d{8,11}'), '[NOMOR_HP]'), (re.compile(r'\\b\\d{16}\\b'), '[NIK]'),\n        (re.compile(r'[\\w.+-]+@[\\w-]+\\.[\\w.]+'), '[EMAIL]')]\n\ndef samarkan(teks: str) -> str:\n    for pola, ganti in POLA:\n        teks = pola.sub(ganti, teks)\n    return teks\n\nklien = anthropic.Anthropic()\nINSTRUKSI = ('Kamu membantu tim CS toko online Indonesia. Baca tiket, lalu panggil tool simpan_saran. '\n             'Prioritas tinggi jika uang pelanggan tertahan atau akun diretas. Balasan sopan, bahasa Indonesia, '\n             'jangan menjanjikan pengembalian dana.')\n\ndef triase(teks_tiket: str) -> Saran:\n    for percobaan in range(2):\n        r = klien.messages.create(\n            model='claude-sonnet-4-5', max_tokens=800, system=INSTRUKSI,\n            tools=[{'name': 'simpan_saran', 'description': 'Simpan hasil triase', 'input_schema': Saran.model_json_schema()}],\n            tool_choice={'type': 'tool', 'name': 'simpan_saran'},\n            messages=[{'role': 'user', 'content': samarkan(teks_tiket)}])\n        try:\n            return Saran.model_validate(r.content[0].input)\n        except ValidationError:\n            continue\n    raise ValueError('Keluaran model tidak valid')\n\n# triase/tasks.py\n@shared_task(autoretry_for=(anthropic.APIConnectionError, anthropic.RateLimitError), retry_backoff=True, max_retries=4, time_limit=60)\ndef proses_tiket(tiket_id):\n    t = Tiket.objects.get(pk=tiket_id)\n    try:\n        s = triase(t.isi)\n    except ValueError:\n        t.status = 'PERLU_MANUAL'; t.save(); return\n    SaranAI.objects.update_or_create(tiket=t, defaults=s.model_dump())\n    t.status = 'MENUNGGU_TINJAUAN'; t.save()\n\n# triase/management/commands/evaluasi_triase.py\nclass Command(BaseCommand):\n    def handle(self, *a, **kw):\n        data = Tiket.objects.filter(label_manual__isnull=False)[:200]\n        benar = sum(triase(t.isi).kategori == t.label_manual for t in data)\n        self.stdout.write(f'Akurasi kategori: {benar}/{len(data)} = {benar / len(data):.0%}')",
  'python', out="samarkan('Saya 081234567890, email andi@mail.com, NIK 1271010101010001')\n-> 'Saya [NOMOR_HP], email [EMAIL], NIK [NIK]'\n\n$ python manage.py evaluasi_triase\nAkurasi kategori: 176/200 = 88%",
  standar='keluaran AI terstruktur dan divalidasi, manusia tetap memutuskan, data pribadi disamarkan, kualitas diukur dengan set evaluasi',
  cek=q('Kenapa saran AI tidak langsung dikirim ke pelanggan?', ['Model bisa keliru; agen CS meninjau dulu (human-in-the-loop)', 'Karena API terlalu lambat', 'Agar biaya lebih mahal'], 0, 'Manusia tetap bertanggung jawab atas balasan.')),
]

PJ_PY = JALUR_M('Backend Python (Django)', 'Menengah',
  'Enam proyek mini (API catatan, webhook aman, rate limiter, unggah foto, pencarian full-text, notifikasi Celery) dan empat proyek besar (LMS berbayar, booking anti-bentrok, SaaS multi-tenant, triase tiket dengan AI), lengkap dengan penyelesaiannya.',
  ['Backend projects', 'Django', 'REST API', 'PostgreSQL', 'Celery', 'AI'], PY_MINI, PY_BESAR)
